content.text:
{
  "name": "WebSocket通信器",
  "name_en": "WebSocket Communicator",
  "manufacturer": "HORIBA",
  "description": "一个非物理的软件通信组件，通过 WebSocket 与实验相关的软件服务或仪器控制端点建立连接，发送命令并接收文本或二进制响应，可用于远程控制、数据交换以及二进制消息回调处理。",
  "description_en": "A non-physical software communication component that connects to experiment-related software services or instrument control endpoints over WebSocket, sends commands, and receives text or binary responses, and supports remote control, data exchange, and binary message callback handling.",
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开 WebSocket 连接并开始监听传入的二进制消息。",
      "description_en": "Open the WebSocket connection and start listening for incoming binary messages."
    },
    {
      "action_name": "auto-send",
      "description": "通过 WebSocket 向服务器发送命令。",
      "description_en": "Send a command to the server over WebSocket."
    },
    {
      "action_name": "auto-opened",
      "description": "检查 WebSocket 连接是否处于打开状态。",
      "description_en": "Check whether the WebSocket connection is open."
    },
    {
      "action_name": "auto-response",
      "description": "获取下一条文本或常规响应消息。",
      "description_en": "Fetch the next text or regular response message."
    },
    {
      "action_name": "auto-binary_response",
      "description": "获取下一条二进制响应消息。",
      "description_en": "Fetch the next binary response message."
    },
    {
      "action_name": "auto-close",
      "description": "关闭 WebSocket 连接。",
      "description_en": "Close the WebSocket connection."
    },
    {
      "action_name": "auto-register_binary_message_callback",
      "description": "注册二进制消息回调函数，使其在收到每条二进制消息时被调用。",
      "description_en": "Register a binary message callback to be invoked for each incoming binary message."
    },
    {
      "action_name": "auto-request_with_response",
      "description": "发送命令并在限定超时时间内等待对应响应。",
      "description_en": "Send a command and wait for the corresponding response within a timeout."
    }
  ],
  "tag_hints": [
    "WebSocket communication",
    "async command-response",
    "binary message streaming",
    "instrument software interface",
    "remote experiment control",
    "HORIBA SDK"
  ]
}

